// 1) Cloneable 方式：super.clone() + 手动重建可变字段
public class Resume implements Cloneable {
    private String name;                  // 不可变引用，浅拷贝即可
    private StringBuilder skills;         // 可变引用，必须深拷贝
    private List<WorkExperience> works;   // 可变集合 + 可变元素，两层都要拷

    public Resume(String name) {
        this.name = name;
        this.skills = new StringBuilder();
        this.works = new ArrayList<>();
    }

    @Override
    public Resume clone() {
        try {
            Resume copy = (Resume) super.clone();          // 浅拷贝：基本值复制值，引用复制地址
            copy.skills = new StringBuilder(this.skills);  // 可变字段重建
            copy.works = new ArrayList<>(this.works.size());
            for (WorkExperience w : this.works) {           // 集合元素也要逐个 clone
                copy.works.add(w.clone());
            }
            return copy;
        } catch (CloneNotSupportedException e) {
            throw new AssertionError("Resume implements Cloneable", e);
        }
    }

    // 2) 拷贝构造函数（Effective Java Item 13 推荐替代方案）
    public Resume(Resume other) {
        this.name = other.name;
        this.skills = new StringBuilder(other.skills);
        this.works = other.works.stream().map(WorkExperience::new).toList();
    }
}

// 3) 序列化深拷贝：一次性递归复制整张对象图
public static <T extends Serializable> T deepCopy(T obj) throws Exception {
    try (var bos = new ByteArrayOutputStream();
         var oos = new ObjectOutputStream(bos)) {
        oos.writeObject(obj);
        try (var bis = new ByteArrayInputStream(bos.toByteArray());
             var ois = new ObjectInputStream(bis)) {
            return (T) ois.readObject();
        }
    }
}
